INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(1, '初級', 'OSの主な役割として正しいものはどれか？', 'アプリケーションの開発', 'ハードウェアとソフトウェアの仲介', 'データの暗号化', 'ネットワーク通信', 'B', 'OSはハードウェアとアプリケーションソフトウェアの間に位置し、リソース管理や制御を行います。'),
(1, '初級', 'Windowsでファイルのコピーを行うコマンドはどれか？', 'move', 'copy', 'paste', 'duplicate', 'B', 'copyコマンドはファイルやディレクトリをコピーするために使用されます。'),
(1, '初級', 'Linuxでカレントディレクトリを表示するコマンドはどれか？', 'cd', 'pwd', 'ls', 'dir', 'B', 'pwd (print working directory) は現在の作業ディレクトリのパスを表示します。'),
(1, '初級', 'プロセスとは何か？', '実行中のプログラム', '保存されたファイル', 'ネットワーク接続', 'ユーザーアカウント', 'A', 'プロセスはメモリ上で実行中のプログラムのインスタンスです。'),
(1, '初級', 'マルチタスクとは何か？', '複数のユーザーが同時に使用すること', '複数のプログラムを同時に実行すること', '複数のCPUを使用すること', '複数のOSを同時に起動すること', 'B', 'マルチタスクは複数のプログラムやプロセスを並行して実行する機能です。'),
(1, '中級', 'デッドロックが発生する条件として誤っているものはどれか？', '相互排除', '保持と待機', 'プリエンプション', '循環待機', 'C', 'デッドロックの4条件は、相互排除、保持と待機、非プリエンプション、循環待機です。プリエンプション（横取り）が可能な場合はデッドロックを回避できます。'),
(1, '中級', 'ページングとは何か？', 'メモリを固定サイズのブロックに分割する方式', 'ディスクを高速化する技術', 'ネットワーク帯域を分割する方法', 'CPUの処理を分散する仕組み', 'A', 'ページングは仮想メモリ管理の一手法で、メモリを固定サイズ（ページ）に分割して管理します。'),
(1, '中級', 'スワップとは何か？', 'メモリとディスク間でデータを交換すること', 'CPUを切り替えること', 'ネットワークを切り替えること', 'ファイルシステムを変更すること', 'A', 'スワップは物理メモリが不足した際に、使用頻度の低いページをディスクに退避させる仕組みです。'),
(1, '中級', 'カーネルとは何か？', 'OSの中核部分', 'アプリケーション', 'デバイスドライバ', 'シェル', 'A', 'カーネルはOSの中核で、ハードウェア制御やリソース管理などの基本機能を提供します。'),
(1, '中級', 'コンテキストスイッチとは何か？', 'プロセス間でCPUを切り替えること', 'ユーザーを切り替えること', 'ネットワークを切り替えること', 'ディスプレイを切り替えること', 'A', 'コンテキストスイッチは、CPUが実行するプロセスを切り替える際に発生する処理です。'),
(1, '上級', 'Copy-on-Write (CoW) の利点は何か？', 'メモリ使用量の削減', 'CPU速度の向上', 'ネットワーク速度の向上', 'ディスク容量の増加', 'A', 'Copy-on-Writeは、実際に書き込みが発生するまでコピーを遅延させることでメモリ効率を向上させます。'),
(1, '上級', 'inode とは何か？', 'ファイルのメタデータを格納する構造体', 'ネットワークノードの識別子', 'プロセスの優先度', 'メモリのアドレス', 'A', 'inode (index node) はUnix系OSでファイルのメタデータ（所有者、権限、タイムスタンプなど）を格納します。'),
(1, '上級', 'セマフォの主な用途は何か？', 'プロセス間の同期制御', 'ネットワーク通信', 'ファイル暗号化', 'メモリ圧縮', 'A', 'セマフォは複数のプロセスやスレッドが共有リソースにアクセスする際の同期を制御する仕組みです。'),
(1, '上級', 'RAID 5 の特徴は何か？', 'ストライピング + 分散パリティ', 'ミラーリングのみ', 'ストライピングのみ', 'パリティなし', 'A', 'RAID 5はデータをストライピングしつつ、パリティ情報を分散配置することで、1台の障害に耐えられます。'),
(1, '上級', 'メモリマップドI/Oの利点は何か？', 'ファイルアクセスの高速化', 'CPU使用率の削減', 'ネットワーク速度の向上', 'ディスク容量の節約', 'A', 'メモリマップドI/Oはファイルをメモリ空間にマッピングし、メモリアクセスと同様に扱うことで高速化します。');
INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(2, '初級', 'OSI参照モデルは何層で構成されているか？', '5層', '7層', '9層', '10層', 'B', 'OSI参照モデルは7層（物理層、データリンク層、ネットワーク層、トランスポート層、セッション層、プレゼンテーション層、アプリケーション層）で構成されています。'),
(2, '初級', 'IPアドレスのクラスCのデフォルトサブネットマスクはどれか？', '255.0.0.0', '255.255.0.0', '255.255.255.0', '255.255.255.255', 'C', 'クラスCのデフォルトサブネットマスクは255.255.255.0です。'),
(2, '初級', 'TCPとUDPの違いとして正しいものはどれか？', 'TCPは信頼性が高く、UDPは高速', 'TCPは高速で、UDPは信頼性が高い', 'どちらも同じ', 'どちらも信頼性が低い', 'A', 'TCPは接続指向で信頼性が高く、UDPはコネクションレスで高速ですが信頼性は低いです。'),
(2, '初級', 'DNSの役割は何か？', 'ドメイン名をIPアドレスに変換', 'データを暗号化', 'ファイルを転送', 'メールを送信', 'A', 'DNS（Domain Name System）はドメイン名をIPアドレスに変換する名前解決サービスです。'),
(2, '初級', 'HTTPSのデフォルトポート番号はどれか？', '80', '443', '8080', '22', 'B', 'HTTPSはポート番号443を使用します（HTTPは80）。'),
(2, '中級', 'CIDR表記で /24 が示すサブネットマスクはどれか？', '255.0.0.0', '255.255.0.0', '255.255.255.0', '255.255.255.128', 'C', '/24は24ビットのネットワーク部を意味し、255.255.255.0に相当します。'),
(2, '中級', 'ARPの役割は何か？', 'IPアドレスからMACアドレスを取得', 'MACアドレスからIPアドレスを取得', 'ドメイン名を解決', 'ルーティング情報を交換', 'A', 'ARP（Address Resolution Protocol）はIPアドレスから対応するMACアドレスを取得するプロトコルです。'),
(2, '中級', 'VLANの主な目的は何か？', 'ネットワークを論理的に分割', 'ネットワーク速度の向上', 'データの暗号化', 'バックアップの自動化', 'A', 'VLAN（Virtual LAN）は物理的なネットワーク構成に依らず、論理的にネットワークをセグメント化します。'),
(2, '中級', 'NATの主な目的は何か？', 'プライベートIPとグローバルIPの変換', 'データの暗号化', 'ルーティングの最適化', 'DNSの高速化', 'A', 'NAT（Network Address Translation）はプライベートIPアドレスをグローバルIPアドレスに変換します。'),
(2, '中級', 'スリーウェイハンドシェイクはどのプロトコルで使用されるか？', 'UDP', 'TCP', 'ICMP', 'ARP', 'B', 'TCPは接続確立時にSYN、SYN-ACK、ACKの3段階のハンドシェイクを行います。'),
(2, '上級', 'BGPの主な用途は何か？', 'AS間のルーティング', 'LAN内のルーティング', 'データの暗号化', '負荷分散', 'A', 'BGP（Border Gateway Protocol）はインターネット上の異なる自律システム（AS）間でルーティング情報を交換します。'),
(2, '上級', 'TCPの輻輳制御アルゴリズムとして正しいものはどれか？', 'スロースタート', 'ファストフォワード', 'クイックリカバリ', 'ラピッドレスポンス', 'A', 'TCPの輻輳制御にはスロースタート、輻輳回避、高速再送、高速リカバリなどのアルゴリズムがあります。'),
(2, '上級', 'MPLS の主な利点は何か？', 'ルーティングの高速化', 'セキュリティの向上', 'コストの削減', '管理の簡素化', 'A', 'MPLS（Multi-Protocol Label Switching）はラベルを用いた高速なパケット転送を実現します。'),
(2, '上級', 'SDNの特徴は何か？', 'コントロールプレーンとデータプレーンの分離', 'ハードウェアの統合', 'ソフトウェアの削除', 'ネットワークの物理的分離', 'A', 'SDN（Software-Defined Networking）は制御機能（コントロールプレーン）とデータ転送機能（データプレーン）を分離します。'),
(2, '上級', 'QUIC プロトコルの特徴は何か？', 'UDP上で動作する高速なトランスポート層プロトコル', 'TCP上で動作する暗号化プロトコル', 'アプリケーション層のルーティングプロトコル', 'データリンク層のプロトコル', 'A', 'QUICはUDPをベースとし、TCPの機能と TLS の暗号化を統合した高速プロトコルです。');
INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(3, '初級', 'SQLで全てのレコードを取得するキーワードはどれか？', 'GET', 'SELECT', 'FETCH', 'RETRIEVE', 'B', 'SELECTはデータベースからデータを取得するSQL文です。'),
(3, '初級', 'PRIMARY KEYの役割は何か？', 'レコードを一意に識別', 'データを暗号化', 'データを圧縮', 'バックアップを作成', 'A', 'PRIMARY KEYはテーブル内の各レコードを一意に識別するための制約です。'),
(3, '初級', 'INNER JOINの動作として正しいものはどれか？', '両テーブルで一致するレコードのみ結合', '左テーブルの全レコードを結合', '右テーブルの全レコードを結合', '全てのレコードを結合', 'A', 'INNER JOINは両方のテーブルで結合条件に一致するレコードのみを返します。'),
(3, '初級', 'INDEXの主な目的は何か？', '検索速度の向上', 'データの暗号化', 'ストレージの節約', 'バックアップの自動化', 'A', 'INDEXはデータの検索を高速化するためのデータ構造です。'),
(3, '初級', 'トランザクションのACID特性の「A」は何を意味するか？', '原子性 (Atomicity)', '可用性 (Availability)', '認証 (Authentication)', '集約 (Aggregation)', 'A', 'Atomicityは、トランザクションが全て成功するか、全て失敗するかのどちらかであることを保証します。'),
(3, '中級', '正規化の主な目的は何か？', 'データの冗長性を排除', 'クエリを高速化', 'ストレージを増加', 'セキュリティを強化', 'A', '正規化はデータの冗長性を排除し、データの整合性を保つための設計手法です。'),
(3, '中級', 'LEFT JOINの動作として正しいものはどれか？', '左テーブルの全レコードと、一致する右テーブルのレコードを結合', '右テーブルの全レコードと、一致する左テーブルのレコードを結合', '一致するレコードのみ結合', '全てのレコードを結合', 'A', 'LEFT JOINは左テーブルの全レコードを保持し、一致する右テーブルのレコードを結合します（一致しない場合はNULL）。'),
(3, '中級', 'デッドロックとは何か？', '複数のトランザクションが互いにロックを待ち合う状態', 'データベースが停止する状態', 'インデックスが破損する状態', 'メモリ不足の状態', 'A', 'デッドロックは複数のトランザクションが互いに相手が保持するロックを待ち合い、進行できなくなる状態です。'),
(3, '中級', 'B-Treeインデックスの特徴は何か？', 'バランスの取れた木構造で高速検索', '線形リスト構造', 'ハッシュテーブル構造', 'スタック構造', 'A', 'B-Treeは自己バランス型の木構造で、検索、挿入、削除がO(log n)で実行できます。'),
(3, '中級', 'ACID特性の「I」（Isolation）は何を意味するか？', '複数のトランザクションが互いに影響しないこと', 'データが一貫していること', 'データが永続化されること', 'データが原子的であること', 'A', 'Isolationは、同時実行されるトランザクションが互いに影響を与えないことを保証します。'),
(3, '上級', 'MVCC (Multi-Version Concurrency Control) の利点は何か？', '読み取りと書き込みがブロックし合わない', 'ストレージ使用量の削減', 'クエリの高速化', 'セキュリティの向上', 'A', 'MVCCは複数のバージョンのデータを保持することで、読み取りと書き込みが互いにブロックしない並行制御を実現します。'),
(3, '上級', 'シャーディングの主な目的は何か？', '水平スケーリングによる負荷分散', '垂直スケーリング', 'データの暗号化', 'バックアップの自動化', 'A', 'シャーディングはデータを複数のデータベースに分割して、負荷を分散させる水平スケーリング手法です。'),
(3, '上級', 'CAP定理のCAPは何を表すか？', 'Consistency, Availability, Partition tolerance', 'Capacity, Authentication, Performance', 'Cache, API, Protocol', 'Compression, Archive, Persistence', 'A', 'CAP定理は、一貫性（Consistency）、可用性（Availability）、分断耐性（Partition tolerance）の3つを同時に満たすことはできないという定理です。'),
(3, '上級', 'クエリオプティマイザの役割は何か？', 'クエリの実行計画を最適化', 'データを圧縮', 'バックアップを作成', 'ユーザー認証', 'A', 'クエリオプティマイザは、SQLクエリの実行計画を分析し、最も効率的な実行方法を選択します。'),
(3, '上級', 'レプリケーションのマスター・スレーブ構成の利点は何か？', '読み取り負荷の分散', '書き込み速度の向上', 'ストレージの削減', 'セキュリティの向上', 'A', 'マスター・スレーブ構成では、読み取りをスレーブに分散させることで、マスターの負荷を軽減できます。');
INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(4, '初級', 'IaaS の「I」は何を意味するか？', 'Internet', 'Infrastructure', 'Integration', 'Intelligence', 'B', 'IaaS（Infrastructure as a Service）はインフラストラクチャをサービスとして提供するモデルです。'),
(4, '初級', 'AWS EC2 とは何か？', '仮想サーバーサービス', 'データベースサービス', 'ストレージサービス', 'ネットワークサービス', 'A', 'EC2（Elastic Compute Cloud）はAWSの仮想サーバーサービスです。'),
(4, '初級', 'AWS S3 の主な用途は何か？', 'オブジェクトストレージ', 'データベース', '仮想サーバー', 'メール送信', 'A', 'S3（Simple Storage Service）はスケーラブルなオブジェクトストレージサービスです。'),
(4, '初級', 'クラウドコンピューティングの利点として正しいものはどれか？', '初期投資の削減', '完全なコントロール', 'オフライン利用', '固定費用', 'A', 'クラウドは従量課金制で初期投資を抑え、必要に応じてスケールできます。'),
(4, '初級', 'PaaS の「P」は何を意味するか？', 'Protocol', 'Platform', 'Process', 'Performance', 'B', 'PaaS（Platform as a Service）はアプリケーション実行環境をサービスとして提供します。'),
(4, '中級', 'AWS Lambda の特徴は何か？', 'サーバーレスコンピューティング', '専用サーバー', '物理サーバー', 'オンプレミス', 'A', 'Lambdaはサーバーの管理不要で、イベント駆動でコードを実行できるサーバーレスサービスです。'),
(4, '中級', 'オートスケーリングの主な目的は何か？', '負荷に応じてリソースを自動調整', 'コストを固定', 'セキュリティを強化', 'データをバックアップ', 'A', 'オートスケーリングは負荷に応じてインスタンス数を自動的に増減させる機能です。'),
(4, '中級', 'AWS VPC の役割は何か？', '仮想プライベートネットワークの構築', 'データベース管理', 'ファイル共有', 'メール配信', 'A', 'VPC（Virtual Private Cloud）はAWS上に論理的に分離されたネットワーク環境を構築します。'),
(4, '中級', 'CDN の主な目的は何か？', 'コンテンツ配信の高速化', 'データベースの最適化', 'サーバーの仮想化', 'セキュリティの強化', 'A', 'CDN（Content Delivery Network）はコンテンツをエッジロケーションにキャッシュして配信を高速化します。'),
(4, '中級', 'マルチリージョンデプロイの利点は何か？', '災害対策と低レイテンシ', 'コスト削減', '管理の簡素化', 'セキュリティの強化', 'A', 'マルチリージョンは地理的に分散してシステムを配置し、災害対策と各地域での低レイテンシを実現します。'),
(4, '上級', 'AWS ECS と EKS の違いは何か？', 'ECSはAWS独自、EKSはKubernetes', 'ECSは無料、EKSは有料', 'ECSは遅い、EKSは高速', 'ECSは古い、EKSは新しい', 'A', 'ECS（Elastic Container Service）はAWS独自のコンテナオーケストレーション、EKS（Elastic Kubernetes Service）はKubernetesのマネージドサービスです。'),
(4, '上級', 'サーバーレスアーキテクチャの利点は何か？', '運用負荷の削減とスケーラビリティ', 'コストの増加', '完全なコントロール', '物理サーバーの管理', 'A', 'サーバーレスはインフラ管理が不要で、自動スケールし、実行時間に応じた課金となります。'),
(4, '上級', 'AWS IAM の主な役割は何か？', 'アクセス制御と認証', 'データベース管理', 'ネットワーク設定', 'ストレージ管理', 'A', 'IAM（Identity and Access Management）はAWSリソースへのアクセス制御と認証を管理します。'),
(4, '上級', 'Terraform の主な用途は何か？', 'Infrastructure as Code', 'コンテナオーケストレーション', 'CI/CDパイプライン', 'モニタリング', 'A', 'Terraformはインフラをコードとして定義・管理するIaCツールです。'),
(4, '上級', 'AWS CloudFormation の利点は何か？', 'インフラのコード化と自動化', 'データベースの最適化', 'アプリケーションのデバッグ', 'ネットワークの監視', 'A', 'CloudFormationはAWSリソースをテンプレートで定義し、自動的にプロビジョニングします。');
INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(5, '初級', 'SQLインジェクションとは何か？', 'SQL文を不正に操作する攻撃', 'サーバーを停止させる攻撃', 'ネットワークを盗聴する攻撃', 'ファイルを削除する攻撃', 'A', 'SQLインジェクションは悪意のあるSQL文を挿入してデータベースを不正操作する攻撃です。'),
(5, '初級', 'HTTPSの「S」は何を意味するか？', 'Secure', 'Simple', 'Server', 'Session', 'A', 'HTTPSのSはSecureを意味し、SSL/TLSによる暗号化通信を行います。'),
(5, '初級', 'パスワードのハッシュ化の目的は何か？', '平文パスワードの保護', 'パスワードの圧縮', 'パスワードの高速化', 'パスワードの共有', 'A', 'ハッシュ化は一方向関数でパスワードを変換し、元に戻せないようにすることで保護します。'),
(5, '初級', 'ファイアウォールの主な役割は何か？', '不正なアクセスをブロック', 'ファイルを暗号化', 'データをバックアップ', 'ウイルスを駆除', 'A', 'ファイアウォールはネットワークトラフィックを監視し、不正なアクセスをブロックします。'),
(5, '初級', '2要素認証の例として正しいものはどれか？', 'パスワード + SMS認証', 'パスワード + パスワード', 'SMS + SMS', 'メール + メール', 'A', '2要素認証は「知っているもの（パスワード）」と「持っているもの（スマホ）」など、異なる2つの要素で認証します。'),
(5, '中級', 'XSS (Cross-Site Scripting) の対策として有効なものはどれか？', '入力値のサニタイズとエスケープ', 'サーバーの再起動', 'ファイアウォールの無効化', 'HTTPSの無効化', 'A', 'XSS対策にはユーザー入力のサニタイズ、HTMLエスケープ、CSP（Content Security Policy）が有効です。'),
(5, '中級', 'CSRF (Cross-Site Request Forgery) の対策として有効なものはどれか？', 'CSRFトークンの使用', 'パスワードの複雑化', 'HTTPSの使用のみ', 'ファイアウォールの設定', 'A', 'CSRF対策にはワンタイムトークン（CSRFトークン）の検証が有効です。'),
(5, '中級', 'ソルトの目的は何か？', 'レインボーテーブル攻撃の防止', 'パスワードの高速化', 'パスワードの圧縮', 'パスワードの共有', 'A', 'ソルトはハッシュ化の際にランダムな値を追加し、同じパスワードでも異なるハッシュ値にすることで攻撃を困難にします。'),
(5, '中級', 'OWASP Top 10 とは何か？', 'Webアプリケーションの重大な脆弱性トップ10', 'セキュリティツールトップ10', 'ハッカーランキング', 'セキュリティ企業ランキング', 'A', 'OWASP Top 10はWebアプリケーションで最も重要なセキュリティリスクをまとめたリストです。'),
(5, '中級', 'ゼロトラストセキュリティの原則は何か？', '全てのアクセスを検証', '内部ネットワークを信頼', 'ファイアウォールのみで防御', 'パスワード認証のみ', 'A', 'ゼロトラストは「信頼しない、常に検証する」という原則で、全てのアクセスを認証・認可します。'),
(5, '上級', 'ペネトレーションテストの主な目的は何か？', 'システムの脆弱性を発見', 'システムを破壊', 'データを盗む', 'ネットワークを遮断', 'A', 'ペネトレーションテストは実際の攻撃を模擬し、システムの脆弱性を発見して改善するためのセキュリティ診断です。'),
(5, '上級', 'WAF (Web Application Firewall) の役割は何か？', 'Webアプリケーションレベルの攻撃を防御', 'ネットワークレベルの攻撃を防御', 'データベースを暗号化', 'ログを管理', 'A', 'WAFはHTTPトラフィックを監視し、SQLインジェクション、XSSなどのWebアプリケーション攻撃を防ぎます。'),
(5, '上級', 'OAuth 2.0 の主な用途は何か？', 'サードパーティアプリへの認可', 'データベースの暗号化', 'ファイルの圧縮', 'ネットワークの監視', 'A', 'OAuth 2.0はユーザーがパスワードを共有せずに、サードパーティアプリケーションに権限を委譲するプロトコルです。'),
(5, '上級', 'JWT (JSON Web Token) の特徴は何か？', 'ステートレスな認証トークン', 'ステートフルなセッション', 'データベース認証', 'ファイルベース認証', 'A', 'JWTはサーバー側でセッションを保持せず、トークン自体に情報を含む署名付きトークンです。'),
(5, '上級', 'ゼロデイ攻撃とは何か？', '未公開の脆弱性を利用した攻撃', '既知の脆弱性を利用した攻撃', 'パスワード総当たり攻撃', 'DoS攻撃', 'A', 'ゼロデイ攻撃はベンダーが脆弱性を認識していない（パッチが存在しない）段階で行われる攻撃です。');
INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(6, '初級', 'オブジェクト指向の三大要素として正しいものはどれか？', 'カプセル化、継承、多態性', 'カプセル化、暗号化、圧縮', '継承、転送、変換', '多態性、単一性、複雑性', 'A', 'オブジェクト指向の三大要素はカプセル化（Encapsulation）、継承（Inheritance）、多態性（Polymorphism）です。'),
(6, '初級', '変数のスコープとは何か？', '変数が有効な範囲', '変数の型', '変数の値', '変数の名前', 'A', 'スコープは変数がアクセス可能な範囲（ローカルスコープ、グローバルスコープなど）を指します。'),
(6, '初級', 'for文とwhile文の違いは何か？', 'forは繰り返し回数が明確な場合に使用', 'forは条件が複雑な場合に使用', 'whileは配列専用', 'whileは使用できない', 'A', 'for文は繰り返し回数が事前に分かっている場合、while文は条件が満たされる間繰り返す場合に適しています。'),
(6, '初級', 'デバッグとは何か？', 'プログラムのバグを見つけて修正すること', 'プログラムを削除すること', 'プログラムを高速化すること', 'プログラムを暗号化すること', 'A', 'デバッグはプログラム内のエラー（バグ）を発見し、修正する作業です。'),
(6, '初級', 'コンパイラとインタプリタの違いは何か？', 'コンパイラは事前に機械語に変換、インタプリタは逐次実行', 'コンパイラは遅く、インタプリタは速い', 'コンパイラは使えない', 'インタプリタは使えない', 'A', 'コンパイラはソースコードを事前に機械語に変換、インタプリタは実行時に1行ずつ解釈します。'),
(6, '中級', 'デザインパターンの「Singleton」の目的は何か？', 'クラスのインスタンスを1つに制限', '複数のインスタンスを生成', 'インスタンスを削除', 'インスタンスを暗号化', 'A', 'Singletonパターンはクラスのインスタンスが1つしか存在しないことを保証します。'),
(6, '中級', 'RESTful APIの特徴は何か？', 'ステートレスで、HTTPメソッドを使用', 'ステートフルで、独自プロトコルを使用', 'データベース専用', 'ファイル転送専用', 'A', 'RESTful APIはステートレスで、GET、POST、PUT、DELETEなどのHTTPメソッドでリソースを操作します。'),
(6, '中級', 'メモリリークとは何か？', '確保したメモリが解放されず残り続けること', 'メモリが多すぎること', 'メモリが暗号化されること', 'メモリが削除されること', 'A', 'メモリリークは不要になったメモリを解放せず、使用可能なメモリが徐々に減少する現象です。'),
(6, '中級', 'ガベージコレクションの役割は何か？', '不要なメモリの自動解放', 'ファイルの圧縮', 'データの暗号化', 'ログの削除', 'A', 'ガベージコレクションは参照されなくなったオブジェクトのメモリを自動的に解放します。'),
(6, '中級', '関数型プログラミングの特徴は何か？', '副作用のない純粋関数の使用', 'グローバル変数の多用', 'ループの多用', 'オブジェクトの継承', 'A', '関数型プログラミングは副作用がなく、同じ入力に対して常に同じ出力を返す純粋関数を重視します。'),
(6, '上級', 'デッドロックの4条件として正しいものはどれか？', '相互排除、保持と待機、非プリエンプション、循環待機', '並行性、一貫性、可用性、分散性', '継承、カプセル化、多態性、抽象化', 'スタック、キュー、リスト、ツリー', 'A', 'デッドロックは相互排除、保持と待機、非プリエンプション、循環待機の4条件が全て揃うと発生します。'),
(6, '上級', 'マイクロサービスアーキテクチャの利点は何か？', '独立したデプロイとスケーラビリティ', 'モノリシックな構造', '低い複雑性', '単一のデータベース', 'A', 'マイクロサービスは各サービスを独立して開発・デプロイでき、個別にスケールできます。'),
(6, '上級', 'SOLID原則の「S」は何を意味するか？', '単一責任の原則 (Single Responsibility)', 'セキュリティの原則 (Security)', 'スピードの原則 (Speed)', 'サイズの原則 (Size)', 'A', 'SOLID原則のSは単一責任の原則で、クラスは1つの責任のみを持つべきという原則です。'),
(6, '上級', 'CI/CDの主な目的は何か？', '継続的インテグレーションとデリバリーの自動化', 'コードの圧縮', 'データの暗号化', 'ログの管理', 'A', 'CI/CDはコードの統合、テスト、デプロイを自動化し、ソフトウェアリリースサイクルを高速化します。'),
(6, '上級', 'ダックタイピングとは何か？', 'オブジェクトの型よりも振る舞いを重視', '型を厳密にチェック', '型を削除', '型を暗号化', 'A', 'ダックタイピングは「アヒルのように歩き、鳴くならそれはアヒル」という考え方で、明示的な型宣言より振る舞いを重視します。');
INSERT INTO questions (genre_id, difficulty, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
(7, '初級', 'アジャイル開発の特徴は何か？', '短いイテレーションで開発', '長期計画で一括開発', '文書重視', '顧客との接触なし', 'A', 'アジャイルは短いスプリント（イテレーション）で開発を繰り返し、変化に柔軟に対応します。'),
(7, '初級', 'スクラムのスプリントの期間として一般的なものはどれか？', '1-4週間', '6ヶ月', '1年', '1日', 'A', 'スクラムのスプリントは通常1〜4週間（多くは2週間）で設定されます。'),
(7, '初級', 'ガントチャートの主な用途は何か？', 'スケジュール管理', 'コスト管理', 'リスク管理', '品質管理', 'A', 'ガントチャートはタスクの開始・終了日を視覚化し、プロジェクトのスケジュールを管理します。'),
(7, '初級', 'WBS (Work Breakdown Structure) の目的は何か？', '作業を階層的に分解', 'コストを計算', 'リスクを評価', 'メンバーを評価', 'A', 'WBSはプロジェクトを管理可能な小さな作業単位に階層的に分解します。'),
(7, '初級', 'KPI とは何か？', '重要業績評価指標', '費用対効果', 'リスク指標', '品質指標', 'A', 'KPI（Key Performance Indicator）は目標達成度を測る重要な指標です。'),
(7, '中級', 'スクラムマスターの主な役割は何か？', 'チームの障害を取り除く', 'コードを書く', 'デザインを作成', '営業をする', 'A', 'スクラムマスターはチームが効率的に作業できるよう、障害を取り除き、スクラムプロセスを促進します。'),
(7, '中級', 'クリティカルパスとは何か？', 'プロジェクト完了までの最長経路', '最短経路', '最安経路', '最速経路', 'A', 'クリティカルパスはプロジェクト完了に必要な最長の作業経路で、遅延が全体に影響します。'),
(7, '中級', 'ベロシティとは何か？', 'スプリントで完了した作業量', 'コードの行数', 'バグの数', '会議の時間', 'A', 'ベロシティはスクラムで1スプリントに完了できる作業量（ストーリーポイント）を示します。'),
(7, '中級', 'リスクマネジメントの4つのステップとして正しいものはどれか？', '識別、分析、対応、監視', '計画、実行、評価、改善', '設計、開発、テスト、デプロイ', '提案、承認、実行、報告', 'A', 'リスクマネジメントはリスクの識別、分析、対応計画、監視・コントロールのプロセスです。'),
(7, '中級', 'MVP (Minimum Viable Product) の目的は何か？', '最小限の機能で顧客フィードバックを得る', '完璧な製品を作る', 'コストを最大化', '全機能を実装', 'A', 'MVPは最小限の機能で製品をリリースし、早期に顧客フィードバックを得て改善します。'),
(7, '上級', 'カンバンとスクラムの主な違いは何か？', 'カンバンはタイムボックスなし、スクラムはスプリント制', 'カンバンは古い、スクラムは新しい', 'カンバンは遅い、スクラムは速い', 'カンバンは使えない', 'A', 'カンバンは継続的フローでタイムボックスがなく、スクラムは固定期間のスプリントで開発します。'),
(7, '上級', 'プロジェクトマネジメントのトライアングル（三重制約）とは何か？', 'スコープ、コスト、時間', 'リスク、品質、人員', '計画、実行、評価', '設計、開発、テスト', 'A', 'プロジェクトのトライアングルはスコープ、コスト、時間の3つの制約で、1つを変えると他に影響します。'),
(7, '上級', 'EVM (Earned Value Management) で使用される指標として正しいものはどれか？', 'PV, EV, AC', 'CPU, RAM, DISK', 'GET, POST, PUT', 'HTML, CSS, JS', 'A', 'EVMはPV（計画価値）、EV（出来高）、AC（実コスト）を使ってプロジェクトの進捗とコストを管理します。'),
(7, '上級', 'ステークホルダー管理の重要性は何か？', 'プロジェクトの成功確率を高める', 'コストを削減', '開発速度を上げる', 'コードの品質を上げる', 'A', 'ステークホルダーの期待を管理し、適切なコミュニケーションを取ることでプロジェクトの成功確率が高まります。'),
(7, '上級', 'SAFe (Scaled Agile Framework) の目的は何か？', '大規模組織でのアジャイル適用', '小規模チーム専用', 'ウォーターフォール開発', '個人開発', 'A', 'SAFeは複数のアジャイルチームを調整し、大規模な組織でアジャイルを実践するためのフレームワークです。');
